1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
8	
9	/**
10	 * Rejects a create-owner request whose E.164 telephone is already used by any existing
11	 * owner, responding 409 via {@link DuplicateTelephoneException}. Runs after
12	 * {@link NormalizeOwnerTelephone} so the request telephone is already in E.164 form;
13	 * existing owners are canonicalized the same way before comparison.
14	 */
15	public class RequireUniqueTelephone {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws DuplicateTelephoneException {
19	        String telephone = request.getTelephone();
20	        for (Owner existing : ownerRepository.findAll()) {
21	            if (telephone.equals(OwnerTelephones.toE164(existing.getTelephone()))) {
22	                throw new DuplicateTelephoneException(request.getTelephone());
23	            }
24	        }
25	    }
26	}
