3	import org.junit.jupiter.api.Test;
4	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
5	import tools.jackson.databind.node.ObjectNode;
6	
7	/** namesake-count: Return 'namesakeCount' = the number of existing owners (before this create) sharing the sa... */
8	class AcceptanceTest extends AcceptanceBase {
9	
10		@Test
11		void coreCountsNamesakes() throws Exception {
12			// The two owners share firstName+lastName (the namesake key) but use DIFFERENT postcodes so
13			// they never fall into the same computed household once keys householdId on
14			// (lastName, postcode) -- otherwise the later household-duplicate block would 409 the setup.
15			String first = "Ann", last = uniqueLastName();
16			ObjectNode a = ownerNode();
17			a.put("firstName", first); a.put("lastName", last); a.put("postcode", "2000");
18			createOwnerOk(a);
19			ObjectNode b = ownerNode();
20			b.put("firstName", first); b.put("lastName", last); b.put("postcode", "2001");
21			int id = createOwnerOk(b);
22			getOwner(id).andExpect(jsonPath("$.namesakeCount").value(1));
23		}
24	}
